/* Shared navigation and page controllers for the multi-page static application. */
document.querySelector('.footer-top').insertAdjacentHTML('afterend','<div class="footer-pages"><a href="movies.html">Movies</a><a href="events.html">Events</a><a href="offers.html">Offers</a><a href="gifts.html">Gift cards</a><a href="bookings.html">My bookings</a><a href="help.html">Help centre</a></div>');
const page=(location.pathname.split('/').pop()||'index.html').replace('.html','');
const params=new URLSearchParams(location.search);
const main=$('main');
const cityName=localStorage.getItem('orbitCityV2')||'Delhi-NCR';
$('#city span').textContent=cityName;$$('.city-name').forEach(e=>e.textContent=cityName);
localStorage.setItem('orbitCity',cityName);
events[0].venue='Sunder Nursery, New Delhi';events[1].venue='The Laugh Store, Dwarka';events[2].venue='Jawaharlal Nehru Stadium, Delhi';events[3].venue='Nehru Park, Chanakyapuri';
cinema='PVR IMAX: Select Citywalk, Saket';
const venues=['PVR IMAX: Select Citywalk, Saket','PVR: Director’s Cut, Vasant Kunj','INOX: Nehru Place','Cinepolis: DLF Avenue, Saket'];
const movieCard=m=>`<a class="movie-card" href="movie.html?id=${movies.indexOf(m)}"><div class="poster"><img src="${m.image}" alt="${m.title}" loading="lazy"><span class="poster-tag">${m.tag}</span><span class="poster-title">${m.title.toUpperCase()}</span><span class="poster-play">Explore film ↗</span></div><h3>${m.title}</h3><p>${m.genre}</p><div class="card-bottom"><span><span class="orange">★</span> <strong>${m.rating}</strong> &nbsp; ${m.votes}</span><b>↗</b></div></a>`;
const eventCard=e=>`<a class="event-card" href="event.html?id=${events.indexOf(e)}"><div class="event-image"><img src="${e.image}" alt="${e.title}"><span>${e.date}</span></div><h3>${e.title}</h3><p>${e.venue}</p><b>₹${e.price} onwards ↗</b></a>`;
const navRoutes={All:'index.html',Movies:'movies.html',Stream:'stream.html',Events:'events.html',Plays:'plays.html',Sports:'sports.html',Activities:'activities.html'};
const actionRoutes={offers:'offers.html',gift:'gifts.html',bookings:'bookings.html',list:'partner.html',events:'events.html',help:'help.html'};
$$('[data-category]').forEach(b=>{const a=document.createElement('a');a.href=navRoutes[b.dataset.category];a.innerHTML=b.innerHTML;a.className=(page===a.href.split('/').pop().replace('.html','')?'active':'');b.replaceWith(a)});
$$('a.logo').forEach(a=>a.href='index.html');
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;let url;if(b.dataset.category)url=navRoutes[b.dataset.category];if(b.dataset.filter)url=navRoutes[b.dataset.filter];if(b.dataset.action)url=actionRoutes[b.dataset.action];if(b.dataset.movie!==undefined)url='movie.html?id='+b.dataset.movie;if(b.dataset.event!==undefined)url='event.html?id='+b.dataset.event;if(b.dataset.eventCategory!==undefined)url=['events.html','plays.html','sports.html','plays.html','activities.html'][+b.dataset.eventCategory];if(b.id==='hero-book')url='movie.html?id='+[2,0,4][heroIndex];if(b.id==='see-all')url='movies.html';if(b.id==='stream-button')url='stream.html';if(b.dataset.city){localStorage.setItem('orbitCityV2',b.dataset.city)}if(url){e.preventDefault();e.stopImmediatePropagation();location.href=url}},true);
function bread(name){return `<div class="breadcrumb"><a href="index.html">Discover</a><span>/</span>${name}</div>`}
function intro(kicker,title,description,theme=''){return `<section class="page-intro ${theme}"><div class="overline">${kicker}</div><h1>${title}<span>✦</span></h1><p>${description}</p><div class="intro-location">⌖ ${escapeHtml(cityName)} <span>CURATED BY ECHO</span></div><div class="intro-echo"></div></section>`}
function content(html){main.innerHTML=html;window.scrollTo(0,0)}
function captured(fn){let html='';const old=modal;modal=h=>{html=h};try{fn()}finally{modal=old}return html}
const headingMap={movies:'Movies',stream:'Stream',events:'Events',plays:'Plays',sports:'Sports',activities:'Experiences',offers:'Offers',gifts:'Gift cards',bookings:'My bookings',partner:'List your show',help:'Help',movie:'Movie details',event:'Event details',booking:'Book tickets'};
if(page!=='index')document.title=`${headingMap[page]||'Discover'} in Delhi | EchoMyShow`;
if(['movies','stream'].includes(page)){
 expanded=true;category=page==='stream'?'Stream':'Movies';
 content(bread(headingMap[page])+intro(page==='stream'?'YOUR SOFA. FRONT ROW.':'THE BIG SCREEN IS CALLING',page==='stream'?'Press play on extraordinary.':'A story for every mood.','Discover your next favourite film. From big-screen spectacles to stories that stay with you.',page==='stream'?'sage':'')+`<div class="catalog-layout"><aside class="filter-panel"><h3>Refine your echo</h3><p>Languages</p><div id="languages">${['All','Hindi','English','Odia','Telugu'].map(l=>`<button class="${l==='All'?'selected':''}" data-lang="${l}">${l==='All'?'All languages':l}</button>`).join('')}</div><p>Genre</p><select id="genre-filter" class="form-field"><option value="All">All genres</option>${['Action','Adventure','Drama','Sci-Fi','Thriller','History'].map(g=>`<option>${g}</option>`).join('')}</select><div class="filter-note">✦<h4>Your seat to something special.</h4><p>Find a story worth stepping out for.</p></div></aside><section class="catalog-results"><div class="catalog-toolbar"><div><h2 id="results-title">${page==='stream'?'Rent. Watch. Repeat.':'Movies in '+escapeHtml(cityName)}</h2><p id="result-count">${movies.length} stories to discover</p></div><select id="sort-filter" aria-label="Sort movies"><option value="popular">Most popular</option><option value="rating">Top rated</option><option value="title">A–Z</option></select></div><div class="movie-grid" id="movie-grid"></div><p id="empty" hidden>No films match these filters. Try another combination.</p><button id="see-all" hidden></button></section></div>`);
 render=function(){let list=movies.filter(m=>(language==='All'||m.lang===language)&&m.title.toLowerCase().includes(query.toLowerCase())&&($('#genre-filter').value==='All'||m.genre.includes($('#genre-filter').value)));const sort=$('#sort-filter').value;if(sort==='rating')list.sort((a,b)=>+b.rating-+a.rating);if(sort==='title')list.sort((a,b)=>a.title.localeCompare(b.title));$('#movie-grid').innerHTML=list.map(movieCard).join('');$('#empty').hidden=!!list.length;$('#result-count').textContent=list.length+' stories to discover'};
 $('#genre-filter').onchange=render;$('#sort-filter').onchange=render;render();
}else if(['events','plays','sports','activities'].includes(page)){
 const c={events:['OUT OF THE ORDINARY','Go where the energy is.','Live music, unforgettable performances and the best nights in Delhi.'],plays:['STORIES, IN PERSON','Take a seat. Feel everything.','Comedy nights, intimate performances and stories that come alive.'],sports:['MAKE SOME NOISE','More than a spectator.','Find your finish line, your team, your next personal best.'],activities:['GO MAKE A MEMORY','Your weekend, reimagined.','Step out of the routine and into something unexpected.']}[page];
 content(bread(headingMap[page])+intro(...c,'night')+`<div class="event-tabs">${[['events','All experiences'],['plays','Comedy & theatre'],['sports','Sports & fitness'],['activities','Weekend picks']].map(([p,t])=>`<a href="${p}.html" class="${page===p?'selected':''}">${t}</a>`).join('')}</div><div class="section-heading"><h2>${page==='events'?'The city’s next big moments':headingMap[page]+' in Delhi'}</h2><span class="muted">Sample experiences · Curated for you</span></div><div class="events-grid large-events" id="events-grid">${events.filter(e=>page==='events'||page==='activities'||(page==='plays'?e.type==='Plays':e.type==='Sports')).map(eventCard).join('')}</div><section class="editorial-banner"><div class="overline">THE ECHO EDIT</div><h2>Less scrolling.<br>More “remember that night?”</h2><a class="primary" href="movies.html">Find your next plan ↗</a></section>`);
}else if(page==='movie'){
 const id=Math.max(0,Math.min(movies.length-1,Number(params.get('id'))||0));selectedMovie=movies[id];const m=selectedMovie;
 content(bread(m.title)+`<section class="film-hero"><div class="film-atmosphere" style="background-image:url('${m.image}')"></div><img class="film-poster" src="${m.image}" alt="${m.title} poster"><div class="film-copy"><div class="eyebrow"><span></span> ${m.tag}</div><h1>${m.title}</h1><div class="film-rating"><strong>★ ${m.rating}<small>/10</small></strong><span>${m.votes}<br>Audience rating</span></div><p>${m.genre} <span>•</span> ${m.lang} <span>•</span> UA</p><div class="format-tags"><span>2D</span><span>IMAX 2D</span><span>DOLBY ATMOS</span></div><a class="primary" href="#showtimes">Find your show ↗</a></div></section><div class="film-body"><section><div class="overline">THE STORY</div><h2>About the movie</h2><p>${m.description}</p><div class="feature-notes"><span>◎ Immersive picture</span><span>◖ Spatial sound</span><span>✦ A big-screen experience</span></div></section><aside><span class="overline">MAKE A NIGHT OF IT</span><h3>A great film deserves<br>a great seat.</h3><p>Choose a cinema and showtime below.</p></aside></div><section id="showtimes" class="showtimes"><div class="section-heading"><div><div class="overline">YOUR NIGHT STARTS HERE</div><h2>Showtimes in ${escapeHtml(cityName)}</h2></div><span class="muted">Sample availability</span></div><div class="date-tabs">${['Today','Tomorrow',new Date(Date.now()+172800000).toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'})].map((x,i)=>`<button class="${i===0?'selected':''}" data-show-date="${escapeHtml(x)}">${x}</button>`).join('')}</div>${venues.map((v,i)=>`<article class="cinema-row"><div><h3>${v}</h3><p>⌖ Delhi-NCR <span>·</span> M-Ticket available</p><span class="amenity">Food & beverage · ${i===0?'IMAX · Laser projection':'Dolby Atmos · Recliner seats'}</span></div><div class="cinema-times">${['10:30 AM','2:15 PM','7:30 PM','10:15 PM'].map((t,j)=>`<a href="booking.html?id=${id}&cinema=${i}&time=${encodeURIComponent(t)}" data-show-link><strong>${t}</strong><small>₹${250+i*50} · ${j===2?'Filling fast':'Available'}</small></a>`).join('')}</div></article>`).join('')}</section><section class="section"><div class="section-heading"><h2>Keep your watchlist interesting</h2><a href="movies.html" class="text-link">Explore movies ↗</a></div><div class="movie-grid">${movies.filter(x=>x!==m).slice(0,5).map(movieCard).join('')}</div></section>`);
 document.addEventListener('click',e=>{const b=e.target.closest('[data-show-date]');if(b){bookingDate=b.dataset.showDate;$$('[data-show-date]').forEach(x=>x.classList.toggle('selected',x===b));$$('[data-show-link]').forEach(a=>{const u=new URL(a.href);u.searchParams.set('date',bookingDate);a.href=u})}});
}else if(page==='booking'){
 selectedMovie=movies[Math.max(0,Math.min(movies.length-1,+params.get('id')||0))];cinema=venues[Math.max(0,Math.min(venues.length-1,+params.get('cinema')||0))];bookingTime=params.get('time')||'7:30 PM';bookingDate=params.get('date')||'Today';ticketPrice=250+Math.max(0,Math.min(venues.length-1,+params.get('cinema')||0))*50;seats=[];
 const oldSeatView=seatView;const oldCheckout=checkout;const oldSuccess=showBooking;
 function bookingLayout(step,html){content(bread('Book tickets')+`<div class="booking-steps"><span class="${step===1?'current':''}">01 &nbsp; Select seats</span><i></i><span class="${step===2?'current':''}">02 &nbsp; Review booking</span><i></i><span class="${step===3?'current':''}">03 &nbsp; Your ticket</span></div><div class="booking-layout"><section class="booking-panel">${html}</section><aside class="booking-aside"><img src="${selectedMovie.image}" alt="${selectedMovie.title}"><div class="overline">YOUR NEXT GREAT MEMORY</div><h2>${selectedMovie.title}</h2><p>${escapeHtml(cinema)}</p><p>${escapeHtml(bookingDate)} · ${escapeHtml(bookingTime)}</p><div class="aside-divider"></div><p>✦ Choose your favourite view<br>◎ Secure demo reservation<br>↗ Your tickets, all in one place</p><small>Demo booking. No payment collected.</small></aside></div>`)}
 seatView=function(){bookingLayout(1,captured(oldSeatView));$$('.seat-grid button').forEach(b=>b.classList.toggle('selected',seats.includes(b.dataset.seat)))};
 checkout=function(){if(!seats.length)return toast('Choose at least one seat to continue.');bookingLayout(2,captured(oldCheckout));$('#checkout').insertAdjacentHTML('beforebegin','<button class="text-link" id="back-seats">← Change seats</button>');$('#back-seats').onclick=seatView};
 showBooking=function(b){bookingLayout(3,captured(()=>oldSuccess(b)));$('#done').replaceWith(Object.assign(document.createElement('a'),{href:'bookings.html',className:'primary',textContent:'View my bookings ↗'}))};seatView();
}else if(page==='event'){
 const ev=events[Math.max(0,Math.min(events.length-1,+params.get('id')||0))];
 content(bread(ev.title)+`<section class="event-detail-hero" style="background-image:linear-gradient(0deg,#0f171ded,transparent),url('${ev.image}')"><span class="event-badge">LIVE IN DELHI</span><div><div class="overline">BE PART OF THE MOMENT</div><h1>${ev.title}</h1><p>${ev.date} &nbsp; · &nbsp; ${ev.venue}</p></div></section><div class="event-detail-body"><section><h2>An experience worth being there for.</h2><p>Switch off the everyday and tune into the energy of a live crowd. Bring your people and make a memory in the heart of Delhi.</p><h3>Before you go</h3><p>Doors open 45 minutes before the event. Carry a valid photo ID. Venue entry and event schedules are subject to the organiser’s terms.</p><div class="feature-notes"><span>♬ Live experience</span><span>⌖ Delhi-NCR</span><span>✦ Limited capacity</span></div></section><aside class="event-reserve"><div class="overline">YOUR SPOT IN THE CROWD</div><h2>₹${ev.price}<small> / person</small></h2><p>${ev.date}<br>${ev.venue}</p><label>Tickets <select class="form-field" id="event-qty">${[1,2,3,4,5,6].map(n=>`<option>${n}</option>`).join('')}</select></label><button class="primary" id="reserve-event">Reserve demo tickets ↗</button><p class="muted">Sample event · No payment collected</p></aside></div>`);
 $('#reserve-event').onclick=()=>{const bs=JSON.parse(localStorage.getItem('orbitBookings')||'[]');const n=+$('#event-qty').value;bs.unshift({title:ev.title,cinema:ev.venue,date:ev.date,time:'6:00 PM',seats:Array.from({length:n},(_,i)=>'General '+(i+1)),total:n*ev.price,id:'ORB-'+Date.now().toString(36).toUpperCase()});localStorage.setItem('orbitBookings',JSON.stringify(bs));location.href='bookings.html'};
}else if(page==='offers'){
 const deals=[['FIRSTECHO','Your first plan, on a better note.','20% OFF','Up to ₹150 off your first movie booking. New demo profiles.','#f6dfcf'],['WEEKDAY','Make Tuesday the new Friday.','BUY 1 GET 1','Selected weekday shows. Maximum benefit ₹250.','#e4e9d9'],['LIVEITUP','Good music. Better company.','₹200 OFF','On live experiences above ₹1,499.','#e5dff0'],['BIGSCREEN','Go big on your next movie night.','15% OFF','IMAX shows above ₹1,000. Maximum benefit ₹200.','#dce8eb']];
 content(bread('Offers')+intro('ECHO PERKS','Great plans. Even better perks.','A little extra to make your next night out feel even better.')+`<section class="offers-grid">${deals.map(d=>`<article class="deal-card" style="--deal:${d[4]}"><div class="deal-top"><span>ECHO EXCLUSIVE</span><b>✳</b><h2>${d[2]}</h2><h3>${d[1]}</h3></div><div class="deal-bottom"><p>${d[3]}</p><button data-copy="${d[0]}">${d[0]} <span>Copy code ↗</span></button><small>Sample offer · Preview only · Cannot be redeemed</small></div></article>`).join('')}</section>`);
}else if(page==='bookings'){
 const bs=JSON.parse(localStorage.getItem('orbitBookings')||'[]');content(bread('My bookings')+intro('YOUR GOOD TIMES, ALL TOGETHER','Plans worth looking forward to.','Your saved movie nights and live experiences, right here.')+(bs.length?`<div class="bookings-grid">${bs.map((b,i)=>`<article class="saved-ticket"><div class="ticket-top"><span>DEMO CONFIRMED</span><b>↗</b></div><h2>${escapeHtml(b.title)}</h2><p>⌖ ${escapeHtml(b.cinema)}</p><div class="ticket-info"><div><small>DATE & TIME</small><strong>${escapeHtml(b.date)} · ${escapeHtml(b.time)}</strong></div><div><small>SEATS / TICKETS</small><strong>${b.seats.map(escapeHtml).join(', ')}</strong></div></div><div class="ticket-perforation"></div><div class="ticket-code"><span>${escapeHtml(b.id)}</span><strong>₹${b.total}</strong></div><button class="text-link" data-booking="${i}">View ticket ↗</button></article>`).join('')}</div>`:`<div class="empty-state"><span>◉</span><h2>Your next great story starts here.</h2><p>You haven't made any plans yet. Let's change that.</p><a class="primary" href="movies.html">Discover movies ↗</a></div>`));
}else if(['gifts','partner','help'].includes(page)){
 const titles={gifts:['GIVE A GREAT MEMORY','The gift of “let’s go”.','For the people who make every plan better.'],partner:['TAKE THE SPOTLIGHT','Your show. A whole new audience.','Bring your next live experience to EchoMyShow.'],help:['WE’RE HERE FOR YOU','A little help goes a long way.','Everything you need to enjoy your next experience.']};
 const body=captured(()=>action({gifts:'gift',partner:'list',help:'help'}[page]));content(bread(headingMap[page])+intro(...titles[page],'sage')+`<section class="utility-panel">${body}</section>`);
}else{
 $('#events-grid').innerHTML=events.map(eventCard).join('');
 $('.discovery strong').textContent='Delhi, make some room for extraordinary.';
 $('.hero').insertAdjacentHTML('afterend',`<section class="city-editorial"><div><div class="overline">THE DELHI EDIT · VOL. 01</div><h2>A city that never runs<br>out of stories.</h2><p>From Saket’s big screens to Delhi’s live stages.<br>Find your next “you had to be there” moment.</p><a href="events.html" class="text-link">Explore Delhi after hours ↗</a></div><a href="events.html" class="editorial-image" style="background-image:url('${photo(photos.concert,900)}')"><span>AFTER HOURS</span><strong>Good nights.<br>Great stories. ↗</strong></a><a href="movies.html" class="editorial-mini"><span>THE BIG SCREEN CLUB</span><strong>Some stories<br>deserve<br>IMAX.</strong><b>Discover the line-up ↗</b></a></section>`);
}
// Search remains available on every page; catalogue updates locally, other pages open search results.
$('#search').value=params.get('q')||'';query=$('#search').value;
$('#search').onkeydown=e=>{if(e.key==='Enter'&&!['movies','stream'].includes(page)){e.preventDefault();e.stopImmediatePropagation();location.href='movies.html?q='+encodeURIComponent(e.target.value)}};
$('#search').addEventListener('input',e=>{if(!['index','movies','stream'].includes(page))e.stopImmediatePropagation()},true);
if(['movies','stream'].includes(page))render();
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&document.activeElement===$('#search')&&!['index','movies','stream'].includes(page)){e.stopImmediatePropagation();location.href='movies.html?q='+encodeURIComponent($('#search').value)}},true);
$('#city').onclick=()=>modal('<div class="overline">FIND YOUR ECHO</div><h2>Choose your city</h2><p>Delhi-NCR is your default location.</p><div class="modal-options">'+['Delhi-NCR','Mumbai','Bengaluru','Hyderabad','Chennai','Pune','Kolkata','Bhubaneswar'].map(c=>`<button data-city="${c}">⌖ ${c}</button>`).join('')+'</div>');

